"""Overwrite the existing two V3 narratives and their separate source trace tables."""
from pathlib import Path
import json
from generate_final_design import ROOT,OUT,write
PATHS={p.stem:p for p in (ROOT/'src/main/java').rglob('*.java')}
PATHS.update({p.name:p for p in (ROOT/'src/main/webapp').rglob('*') if p.is_file()})
def source(key,needle,text):
 p=PATHS[key];s=p.read_text(encoding='utf-8');i=s.find(needle)
 if i<0:raise RuntimeError(key+': missing anchor '+needle)
 line=s[:i].count('\n')+1
 return {'text':text,'path':p.relative_to(ROOT).as_posix(),'line':line,'source':s.splitlines()[line-1].strip()}
def ref(key,needle,text):return (key,needle,text)
class Scenario:
 def __init__(self,module,title,pre):self.module=module;self.title=title;self.pre=pre;self.report=[];self.technical=[]
 def g(self,text,*refs):
  rn=len(self.report)+1;first=len(self.technical)+1
  for key,needle,action in refs:self.technical.append({'n':len(self.technical)+1,'report':rn,**source(key,needle,action)})
  self.report.append({'n':rn,'text':text,'technicalFrom':first,'technicalTo':len(self.technical)})
 def export(self):
  pre=f'# Scenario V3 — Module {self.module}: {self.title}\n\n'+self.pre+'\n\nCác bước dưới đây chỉ là happy case. Constructor khởi tạo tham chiếu, setter void; bên gọi giữ object. Nhóm hydrate graph con/lặp được diễn đạt gọn, nguồn chi tiết nằm ở bảng truy vết riêng. HTTP được container dispatch, không có lời gọi handler vào chính nó.\n\n'
  md=pre+'\n'.join(f'{r["n"]}. {r["text"]}' for r in self.report)
  md+='\n\n## Mapping truy vết\n\n| Bước V3 | Dòng truy vết |\n|---|---|\n'+'\n'.join(f'| {r["n"]} | {r["technicalFrom"]}–{r["technicalTo"]} |' for r in self.report)
  md+=f'\n\n[Bảng truy vết source](Scenario_V3_Ky_thuat_Module{self.module}.md).\n'
  trace=f'# Bảng truy vết chi tiết — Module {self.module}\n\nĐi kèm [V3 chính](Scenario_V3_Module{self.module}.md). Đây là bằng chứng source kết hợp regression runtime, không phải instrumentation log từng setter. Các dòng dưới đây giải thích caller/query/đóng gói/return; không biến chúng thành hàng trăm bước trong V3 chính.\n\nDAO() sở hữu connection, DAO(Connection) mượn; chỉ owner commit/close. Các DAO con dùng cùng connection khi hydrate trong transaction. Filter mapping REQUEST kiểm CSRF/role trước handler; JSP chỉ render và gửi scalar. Date ở Java là java.util.Date, ID/count business Integer, tiền BigDecimal; private date methods dùng DAO6.zone().\n\n| Dòng | Bước V3 | Caller và thao tác thật | Nguồn |\n|---|---|---|---|\n'
  for t in self.technical:trace+=f'| {t["n"]} | {t["report"]} | {t["text"]} | [{Path(t["path"]).name}:{t["line"]}](../../{t["path"]}#L{t["line"]}) |\n'
  write(f'Scenario_V3_Module{self.module}.md',md);write(f'Scenario_V3_Ky_thuat_Module{self.module}.md',trace)
  return {'module':self.module,'report':self.report,'technical':self.technical}

