  ref('VehicleDAO6','Vehicle6 saved=findById(id)','DAO readback graph trong transaction, commit rồi return saved; mã xe chỉ getter dẫn xuất.'),
  ref('VehicleServlet6','c.put("vehicleId",saved.getId())','Servlet giữ id xe, redirect booking/context; form chọn xe mới, giữ ngày/nội dung.'),
